package cli

import (
	"database/sql"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

func semanticRegressionGraphDB(t *testing.T) *sql.DB {
	t.Helper()
	db, err := sql.Open(sqliteDriverName, filepath.Join(t.TempDir(), "graph.sqlite"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = db.Close() })
	for _, statement := range []string{
		`CREATE TABLE symbols (id TEXT PRIMARY KEY, name TEXT, qualified_name TEXT, kind TEXT, file_path TEXT, language TEXT)`,
		`CREATE TABLE files (path TEXT PRIMARY KEY, language TEXT)`,
		`CREATE TABLE relations (from_id TEXT, to_id TEXT, type TEXT, confidence REAL, reason TEXT, warning_codes TEXT)`,
		`CREATE TABLE runtime_traces (id INTEGER PRIMARY KEY AUTOINCREMENT, imported_at TEXT NOT NULL, source_path TEXT NOT NULL, from_id TEXT NOT NULL, to_id TEXT NOT NULL, observed_type TEXT, matched_static_edge INTEGER NOT NULL)`,
		`INSERT INTO symbols VALUES ('caller-id','Caller','pkg.Caller','function','internal/caller.go','Go')`,
		`INSERT INTO symbols VALUES ('target-id','Target','pkg.Target','method','internal/target.go','Go')`,
		`INSERT INTO relations VALUES ('caller-id','target-id','CALLS',1,'static call','[]')`,
		`INSERT INTO runtime_traces(imported_at,source_path,from_id,to_id,observed_type,matched_static_edge) VALUES ('2026-09-18T00:00:00Z','traces/run.ndjson','target-id','caller-id','OBSERVED_CALL',0)`,
	} {
		if _, err := db.Exec(statement); err != nil {
			t.Fatalf("graph fixture %q: %v", statement, err)
		}
	}
	return db
}

func TestSemanticGraphCypherPredicatesDirectionsAndLimits(t *testing.T) {
	forward := `MATCH (a)-[r]->(b) WHERE a.name = "Caller" AND a.kind = "function" AND a.file_path CONTAINS "internal" AND b.qualified_name = "pkg.Target" AND b.kind = "method" AND b.language CONTAINS "Go" AND r.type = "calls" AND r.reason CONTAINS "first" AND r.reason CONTAINS "second" RETURN a,r,b LIMIT 3`
	filters, ok := parseCypherGraphQuery(forward)
	if !ok {
		t.Fatal("forward Cypher query was not parsed")
	}
	if filters.FromName != "Caller" || filters.FromKind != "function" || filters.FromNameContains != "internal" || filters.ToName != "pkg.Target" || filters.ToKind != "method" || filters.ToNameContains != "Go" || filters.Type != "CALLS" || filters.Text != "first second" || filters.Limit != 3 {
		t.Fatalf("forward filters = %+v", filters)
	}

	reverse, ok := parseCypherGraphQuery(`MATCH (a)<-[r:USES_TYPE]-(b) WHERE a.qualified_name = "pkg.Target" AND b.name CONTAINS "Caller" RETURN count(r) LIMIT 1`)
	if !ok || !reverse.Count || reverse.Type != "USES_TYPE" || reverse.ToName != "pkg.Target" || reverse.FromNameContains != "Caller" || reverse.Limit != 1 {
		t.Fatalf("reverse filters = %+v ok=%t", reverse, ok)
	}
	for _, invalid := range []string{"plain text", `MATCH (a)-[r]-(b) RETURN r`, `MATCH (a)->[r]-(b) RETURN r`} {
		if got, ok := parseCypherGraphQuery(invalid); ok {
			t.Fatalf("invalid query parsed: %q => %+v", invalid, got)
		}
	}
}

func TestSemanticGraphCypherPredicateMatrix(t *testing.T) {
	tests := []struct {
		alias, field, op, value string
		want                    graphQueryFilters
	}{
		{"a", "qualified_name", "=", "from.qual", graphQueryFilters{FromName: "from.qual"}},
		{"a", "language", "CONTAINS", "Rust", graphQueryFilters{FromNameContains: "Rust"}},
		{"b", "name", "=", "target", graphQueryFilters{ToName: "target"}},
		{"b", "file_path", "CONTAINS", "service", graphQueryFilters{ToNameContains: "service"}},
		{"r", "type", "=", "calls", graphQueryFilters{Type: "CALLS"}},
		{"x", "unknown", "=", "ignored", graphQueryFilters{}},
	}
	for _, tc := range tests {
		var got graphQueryFilters
		applyCypherPredicate(&got, tc.alias, tc.field, tc.op, tc.value)
		if !reflect.DeepEqual(got, tc.want) {
			t.Fatalf("%s.%s %s: got %+v want %+v", tc.alias, tc.field, tc.op, got, tc.want)
		}
	}
}

func TestSemanticRuntimeTraceWhereSQLCoversEveryEndpointFilter(t *testing.T) {
	filters := graphQueryFilters{
		From: "from-id", To: "to-id", Text: "trace", FromName: "From", ToName: "To",
		FromKind: "function", ToKind: "method", FromNameContains: "source", ToNameContains: "target",
	}
	where, args := runtimeTraceWhereSQL(filters)
	for _, clause := range []string{
		"from_id = ?", "to_id = ?", "observed_type LIKE ?", "source_path LIKE ?",
		"from_id IN (SELECT id FROM symbols WHERE name = ?", "to_id IN (SELECT id FROM symbols WHERE name = ?",
		"from_id IN (SELECT id FROM symbols WHERE kind = ?)", "to_id IN (SELECT id FROM symbols WHERE kind = ?)",
		"from_id IN (SELECT id FROM symbols WHERE name LIKE ?", "to_id IN (SELECT id FROM symbols WHERE name LIKE ?",
	} {
		if !strings.Contains(where, clause) {
			t.Fatalf("WHERE clause missing %q: %s", clause, where)
		}
	}
	want := []any{"from-id", "to-id", "%trace%", "%trace%", "%trace%", "%trace%", "From", "From", "To", "To", "function", "method", "%source%", "%source%", "%source%", "%source%", "%target%", "%target%", "%target%", "%target%"}
	if !reflect.DeepEqual(args, want) {
		t.Fatalf("runtime trace args = %#v, want %#v", args, want)
	}
	if empty, args := runtimeTraceWhereSQL(graphQueryFilters{}); empty != " WHERE 1=1" || len(args) != 0 {
		t.Fatalf("empty filters = %q %#v", empty, args)
	}
}

func TestSemanticGraphQueriesDirectionsLimitsEmptyAndRuntimeTrace(t *testing.T) {
	db := semanticRegressionGraphDB(t)
	forward, ok := parseCypherGraphQuery(`MATCH (a)-[r:CALLS]->(b) WHERE a.name = "Caller" AND b.name = "Target" RETURN a,r,b LIMIT 1`)
	if !ok {
		t.Fatal("forward query did not parse")
	}
	records, err := queryGraphRelations(db, forward, 10)
	if err != nil || len(records) != 1 || records[0].FromID != "caller-id" || records[0].ToID != "target-id" {
		t.Fatalf("forward records=%+v err=%v", records, err)
	}
	reverse, ok := parseCypherGraphQuery(`MATCH (a)<-[r:CALLS]-(b) WHERE a.name = "Target" AND b.name = "Caller" RETURN a,r,b`)
	if !ok {
		t.Fatal("reverse query did not parse")
	}
	records, err = queryGraphRelations(db, reverse, 1)
	if err != nil || len(records) != 1 || records[0].FromID != "caller-id" || records[0].ToID != "target-id" {
		t.Fatalf("reverse records=%+v err=%v", records, err)
	}
	if records, err = queryGraphRelations(db, graphQueryFilters{FromName: "Missing"}, 10); err != nil || records == nil || len(records) != 0 {
		t.Fatalf("empty query must return []: records=%#v err=%v", records, err)
	}
	traceFilters := graphQueryFilters{Type: "RUNTIME_TRACE", FromName: "Target", ToKind: "function", Text: "run.ndjson"}
	if records, err = queryGraphRelations(db, traceFilters, 1); err != nil || len(records) != 1 || records[0].RecordType != "runtime_trace" || records[0].Confidence != 0.5 || !reflect.DeepEqual(records[0].WarningCodes, []string{"UNMATCHED_STATIC_EDGE"}) {
		t.Fatalf("runtime trace records=%+v err=%v", records, err)
	}
	if count, err := countGraphRelations(db, graphQueryFilters{Type: "RUNTIME_TRACE"}); err != nil || count != 1 {
		t.Fatalf("runtime trace count=%d err=%v", count, err)
	}
}
package cli

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/spf13/cobra"
)

func semanticRegressionPathDigest(t *testing.T, repoDir, clean string, ignore brainIgnore) ([32]byte, int64) {
	t.Helper()
	h := sha256.New()
	var total int64
	if err := appendWorktreePathContent(h, &total, repoDir, clean, ignore); err != nil {
		t.Fatal(err)
	}
	var sum [32]byte
	copy(sum[:], h.Sum(nil))
	return sum, total
}

func TestSemanticWorktreePathFingerprintIncludesFilesAndExcludesIgnoredAndSymlinks(t *testing.T) {
	repoDir := t.TempDir()
	for rel, body := range map[string]string{
		"untracked/kept.go":         "package kept\n",
		"untracked/ignored/key.pem": "secret-one\n",
	} {
		path := filepath.Join(repoDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	external := filepath.Join(t.TempDir(), "external.go")
	if err := os.WriteFile(external, []byte("external-one\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	symlink := filepath.Join(repoDir, "untracked", "linked.go")
	if err := os.Symlink(external, symlink); err != nil {
		t.Skipf("symlink unavailable: %v", err)
	}
	ignore := brainIgnore{patterns: []string{"untracked/ignored/**"}}
	base, baseBytes := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
	if baseBytes == 0 {
		t.Fatal("included worktree file contributed no fingerprint bytes")
	}
	if _, singleBytes := semanticRegressionPathDigest(t, repoDir, "untracked/kept.go", ignore); singleBytes == 0 {
		t.Fatal("top-level untracked file contributed no fingerprint bytes")
	}
	if directLink, linkBytes := semanticRegressionPathDigest(t, repoDir, "untracked/linked.go", ignore); directLink != sha256.Sum256(nil) || linkBytes != 0 {
		t.Fatalf("top-level symlink contributed to fingerprint: %x bytes=%d", directLink, linkBytes)
	}
	if err := os.WriteFile(filepath.Join(repoDir, "untracked", "kept.go"), []byte("package changed\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	included, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
	if included == base {
		t.Fatal("changing an included file did not change the worktree fingerprint")
	}
	if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored", "key.pem"), []byte("secret-two\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	ignored, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
	if ignored != included {
		t.Fatal("changing an ignored file changed the worktree fingerprint")
	}
	if err := os.WriteFile(external, []byte("external-two\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	linked, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
	if linked != ignored {
		t.Fatal("changing a symlink target outside the repository changed the fingerprint")
	}
	missing, missingBytes := semanticRegressionPathDigest(t, repoDir, "missing", ignore)
	if missing != sha256.Sum256(nil) || missingBytes != 0 {
		t.Fatalf("missing path contributed to fingerprint: %x bytes=%d", missing, missingBytes)
	}
}

func TestSemanticFailedReplacementPreservesReadableActiveGeneration(t *testing.T) {
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
	opts := Options{Env: env, Runner: runner, Now: func() time.Time { return time.Date(2026, 9, 18, 0, 0, 0, 0, time.UTC) }}
	cmd := &cobra.Command{Use: "index"}
	if err := runSemanticIndex(context.Background(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
		t.Fatalf("initial index: %v", err)
	}
	brainDir, err := brainDirForKey(env, "gh/example/repo")
	if err != nil {
		t.Fatal(err)
	}
	before, err := loadBrainManifest(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	oldStore := filepath.Join(brainDir, filepath.FromSlash(before.Sources.Semantic.StorePath))
	key := fakeCommandKey("entire", "graph", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network")
	runner.responses[key] = fakeCommandResponse{stdout: `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","warnings":[],"partial_failures":[]}` + "\n" + `{"record_type":"symbol"}` + "\n"}
	if err := runSemanticIndex(context.Background(), cmd, opts, semanticIndexOptions{graphBinary: "entire", force: true}, repoDir); err == nil {
		t.Fatal("malformed replacement generation unexpectedly succeeded")
	}
	after, err := loadBrainManifest(brainDir)
	if err != nil {
		t.Fatal(err)
	}
	if after.Sources.Semantic.StorePath != before.Sources.Semantic.StorePath || after.Sources.Semantic.GenerationPath != before.Sources.Semantic.GenerationPath {
		t.Fatalf("failed replacement changed active generation: before=%+v after=%+v", before.Sources.Semantic, after.Sources.Semantic)
	}
	db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(oldStore))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var symbols int
	if err := db.QueryRow(`SELECT COUNT(*) FROM symbols`).Scan(&symbols); err != nil || symbols != 1 {
		t.Fatalf("old generation is not readable after failed replacement: symbols=%d err=%v", symbols, err)
	}
}

