 37		filters, ok := parseCypherGraphQuery(forward)
 38		if !ok {
 39			t.Fatal("forward Cypher query was not parsed")
 40		}
 41		if filters.FromName != "Caller" || filters.FromKind != "function" || filters.FromNameContains != "internal" || filters.ToName != "pkg.Target" || filters.ToKind != "method" || filters.ToNameContains != "Go" || filters.Type != "CALLS" || filters.Text != "first second" || filters.Limit != 3 {
 42			t.Fatalf("forward filters = %+v", filters)
 43		}
