 15	func semanticRegressionPathDigest(t *testing.T, repoDir, clean string, ignore brainIgnore) ([32]byte, int64) {
 16		t.Helper()
 17		h := sha256.New()
 18		var total int64
 19		if err := appendWorktreePathContent(h, &total, repoDir, clean, ignore); err != nil {
 20			t.Fatal(err)
 21		}
 22		var sum [32]byte
 23		copy(sum[:], h.Sum(nil))
 24		return sum, total
 25	}
 26	
 27	func TestSemanticWorktreePathFingerprintIncludesFilesAndExcludesIgnoredAndSymlinks(t *testing.T) {
 28		repoDir := t.TempDir()
 29		for rel, body := range map[string]string{
 30			"untracked/kept.go":         "package kept\n",
 31			"untracked/ignored/key.pem": "secret-one\n",
 32		} {
 33			path := filepath.Join(repoDir, filepath.FromSlash(rel))
 34			if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
 35				t.Fatal(err)
 36			}
 37			if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
 38				t.Fatal(err)
 39			}
 40		}
 41		external := filepath.Join(t.TempDir(), "external.go")
 42		if err := os.WriteFile(external, []byte("external-one\n"), 0o600); err != nil {
 43			t.Fatal(err)
 44		}
 45		symlink := filepath.Join(repoDir, "untracked", "linked.go")
 46		if err := os.Symlink(external, symlink); err != nil {
 47			t.Skipf("symlink unavailable: %v", err)
 48		}
 49		ignore := brainIgnore{patterns: []string{"untracked/ignored/**"}}
 50		base, baseBytes := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 51		if baseBytes == 0 {
 52			t.Fatal("included worktree file contributed no fingerprint bytes")
 53		}
 54		if _, singleBytes := semanticRegressionPathDigest(t, repoDir, "untracked/kept.go", ignore); singleBytes == 0 {
 55			t.Fatal("top-level untracked file contributed no fingerprint bytes")
 56		}
 57		if directLink, linkBytes := semanticRegressionPathDigest(t, repoDir, "untracked/linked.go", ignore); directLink != sha256.Sum256(nil) || linkBytes != 0 {
 58			t.Fatalf("top-level symlink contributed to fingerprint: %x bytes=%d", directLink, linkBytes)
 59		}
 60		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "kept.go"), []byte("package changed\n"), 0o600); err != nil {
 61			t.Fatal(err)
 62		}
 63		included, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 64		if included == base {
 65			t.Fatal("changing an included file did not change the worktree fingerprint")
 66		}
 67		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored", "key.pem"), []byte("secret-two\n"), 0o600); err != nil {
 68			t.Fatal(err)
 69		}
 70		ignored, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 71		if ignored != included {
 72			t.Fatal("changing an ignored file changed the worktree fingerprint")
 73		}
 74		if err := os.WriteFile(external, []byte("external-two\n"), 0o600); err != nil {
 75			t.Fatal(err)
 76		}
 77		linked, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 78		if linked != ignored {
 79			t.Fatal("changing a symlink target outside the repository changed the fingerprint")
 80		}
 81		missing, missingBytes := semanticRegressionPathDigest(t, repoDir, "missing", ignore)
 82		if missing != sha256.Sum256(nil) || missingBytes != 0 {
 83			t.Fatalf("missing path contributed to fingerprint: %x bytes=%d", missing, missingBytes)
 84		}
 85	}
