 87	func TestSemanticFailedReplacementPreservesReadableActiveGeneration(t *testing.T) {
 88		repoDir := t.TempDir()
 89		env := semanticTestEnv(t, repoDir)
 90		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
 91		opts := Options{Env: env, Runner: runner, Now: func() time.Time { return time.Date(2026, 9, 18, 0, 0, 0, 0, time.UTC) }}
 92		cmd := &cobra.Command{Use: "index"}
 93		if err := runSemanticIndex(context.Background(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
 94			t.Fatalf("initial index: %v", err)
 95		}
 96		brainDir, err := brainDirForKey(env, "gh/example/repo")
 97		if err != nil {
 98			t.Fatal(err)
 99		}
100		before, err := loadBrainManifest(brainDir)
101		if err != nil {
102			t.Fatal(err)
103		}
104		oldStore := filepath.Join(brainDir, filepath.FromSlash(before.Sources.Semantic.StorePath))
105		key := fakeCommandKey("entire", "graph", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network")
106		runner.responses[key] = fakeCommandResponse{stdout: `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"aaa111","tree":"tree111","warnings":[],"partial_failures":[]}` + "\n" + `{"record_type":"symbol"}` + "\n"}
107		if err := runSemanticIndex(context.Background(), cmd, opts, semanticIndexOptions{graphBinary: "entire", force: true}, repoDir); err == nil {
108			t.Fatal("malformed replacement generation unexpectedly succeeded")
109		}
110		after, err := loadBrainManifest(brainDir)
111		if err != nil {
112			t.Fatal(err)
113		}
114		if after.Sources.Semantic.StorePath != before.Sources.Semantic.StorePath || after.Sources.Semantic.GenerationPath != before.Sources.Semantic.GenerationPath {
115			t.Fatalf("failed replacement changed active generation: before=%+v after=%+v", before.Sources.Semantic, after.Sources.Semantic)
116		}
117		db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(oldStore))
118		if err != nil {
119			t.Fatal(err)
120		}
121		defer db.Close()
122		var symbols int
123		if err := db.QueryRow(`SELECT COUNT(*) FROM symbols`).Scan(&symbols); err != nil || symbols != 1 {
124			t.Fatalf("old generation is not readable after failed replacement: symbols=%d err=%v", symbols, err)
125		}
126	}

