 485	func parseGraphQuery(query string) graphQueryFilters {
 486		if filters, ok := parseCypherGraphQuery(query); ok {
 487			return filters
 488		}
 489		var filters graphQueryFilters
 490		for _, field := range strings.Fields(query) {
 491			key, value, ok := strings.Cut(field, ":")
 492			if !ok {
 493				if filters.Text == "" {
 494					filters.Text = field
 495				} else {
 496					filters.Text += " " + field
 497				}
 498				continue
 499			}
 500			switch strings.ToLower(key) {
 501			case "type", "relation":
 502				filters.Type = strings.ToUpper(value)
 503			case "from":
 504				filters.From = value
 505			case "to":
 506				filters.To = value
 507			default:
 508				if filters.Text == "" {
 509					filters.Text = field
 510				} else {
 511					filters.Text += " " + field
 512				}
 513			}
 514		}
 515		return filters
