 563	func cypherRelationDirection(left, right string) (bool, bool) {
 564		switch {
 565		case left == "-" && right == "->":
 566			return false, true
 567		case left == "<-" && right == "-":
 568			return true, true
 569		default:
 570			return false, false
 571		}
 572	}
