 518	var (
 519		cypherRelationRe    = regexp.MustCompile(`(?is)\bMATCH\s*\(\s*[A-Za-z_][A-Za-z0-9_]*\s*\)\s*(<-|-)\s*\[\s*[A-Za-z_][A-Za-z0-9_]*\s*(?::\s*([A-Za-z0-9_]+))?\s*\]\s*(->|-)\s*\(\s*[A-Za-z_][A-Za-z0-9_]*\s*\)`)
 520		cypherLimitRe       = regexp.MustCompile(`(?is)\bLIMIT\s+([0-9]+)\b`)
 521		cypherReturnCountRe = regexp.MustCompile(`(?is)\bRETURN\s+count\s*\(\s*(?:\*|[A-Za-z_][A-Za-z0-9_]*)\s*\)`)
 522		cypherWhereRe       = regexp.MustCompile(`(?is)\bWHERE\s+(.+?)(?:\bRETURN\b|\bLIMIT\b|$)`)
 523		cypherPredRe        = regexp.MustCompile(`(?is)\b([abr])\.(name|qualified_name|kind|file_path|language|type|reason)\s*(=|CONTAINS)\s*['"]([^'"]+)['"]`)
 524	)
 525	
 526	func parseCypherGraphQuery(query string) (graphQueryFilters, bool) {
 527		if !strings.Contains(strings.ToUpper(query), "MATCH") {
 528			return graphQueryFilters{}, false
 529		}
 530		match := cypherRelationRe.FindStringSubmatch(query)
 531		if match == nil {
 532			return graphQueryFilters{}, false
 533		}
 534		reverse, ok := cypherRelationDirection(match[1], match[3])
 535		if !ok {
 536			return graphQueryFilters{}, false
 537		}
 538		filters := graphQueryFilters{}
 539		if len(match) > 2 && strings.TrimSpace(match[2]) != "" {
 540			filters.Type = strings.ToUpper(strings.TrimSpace(match[2]))
 541		}
 542		filters.Count = cypherReturnCountRe.MatchString(query)
 543		if limit := cypherLimitRe.FindStringSubmatch(query); len(limit) == 2 {
 544			if n, err := strconv.Atoi(limit[1]); err == nil && n > 0 {
 545				filters.Limit = n
 546			}
 547		}
 548		if where := cypherWhereRe.FindStringSubmatch(query); len(where) == 2 {
 549			for _, pred := range cypherPredRe.FindAllStringSubmatch(where[1], -1) {
 550				if len(pred) != 5 {
 551					continue
 552				}
 553				alias, field, op, value := strings.ToLower(pred[1]), strings.ToLower(pred[2]), strings.ToUpper(pred[3]), strings.TrimSpace(pred[4])
 554				applyCypherPredicate(&filters, alias, field, op, value)
 555			}
 556		}
 557		if reverse {
 558			filters = reverseCypherEndpointFilters(filters)
 559		}
 560		return filters, true
 561	}
 562	
 563	func cypherRelationDirection(left, right string) (bool, bool) {
 564		switch {
 565		case left == "-" && right == "->":
 566			return false, true
 567		case left == "<-" && right == "-":
 568			return true, true
 569		default:
 570			return false, false
 571		}
 572	}
 573	
 574	func reverseCypherEndpointFilters(filters graphQueryFilters) graphQueryFilters {
 575		filters.From, filters.To = filters.To, filters.From
 576		filters.FromKind, filters.ToKind = filters.ToKind, filters.FromKind
 577		filters.FromName, filters.ToName = filters.ToName, filters.FromName
 578		filters.FromNameContains, filters.ToNameContains = filters.ToNameContains, filters.FromNameContains
 579		return filters
 580	}
