 582	func applyCypherPredicate(filters *graphQueryFilters, alias, field, op, value string) {
 583		switch alias + "." + field + "." + op {
 584		case "a.name.=":
 585			filters.FromName = value
 586		case "a.qualified_name.=":
 587			filters.FromName = value
 588		case "a.kind.=":
 589			filters.FromKind = value
 590		case "a.name.CONTAINS", "a.qualified_name.CONTAINS", "a.file_path.CONTAINS", "a.language.CONTAINS":
 591			filters.FromNameContains = value
 592		case "b.name.=":
 593			filters.ToName = value
 594		case "b.qualified_name.=":
 595			filters.ToName = value
 596		case "b.kind.=":
 597			filters.ToKind = value
 598		case "b.name.CONTAINS", "b.qualified_name.CONTAINS", "b.file_path.CONTAINS", "b.language.CONTAINS":
 599			filters.ToNameContains = value
 600		case "r.type.=":
 601			filters.Type = strings.ToUpper(value)
 602		case "r.reason.CONTAINS":
 603			if filters.Text == "" {
 604				filters.Text = value
 605			} else {
 606				filters.Text += " " + value
 607			}
 608		}
 609	}
