 39		}
 40		if filters.FromName != "Caller" || filters.FromKind != "function" || filters.FromNameContains != "internal" || filters.ToName != "pkg.Target" || filters.ToKind != "method" || filters.ToNameContains != "Go" || filters.Type != "CALLS" || filters.Text != "first second" || filters.Limit != 3 {
