 35		forward := `MATCH (a)-[r]->(b) WHERE a.name = "Caller" AND a.kind = "function" AND a.file_path CONTAINS "internal" AND b.qualified_name = "pkg.Target" AND b.kind = "method" AND b.language CONTAINS "Go" AND r.type = "calls" AND r.reason CONTAINS "first" AND r.reason CONTAINS "second" RETURN a,r,b LIMIT 3`
 36		filters, ok := parseCypherGraphQuery(forward)
 37		if !ok {
 38			t.Fatal("forward Cypher query was not parsed")
 39		}
 40		if filters.FromName != "Caller" || filters.FromKind != "function" || filters.FromNameContains != "internal" || filters.ToName != "pkg.Target" || filters.ToKind != "method" || filters.ToNameContains != "Go" || filters.Type != "CALLS" || filters.Text != "first second" || filters.Limit != 3 {
 41			t.Fatalf("forward filters = %+v", filters)
 42		}
 43	
 44		reverse, ok := parseCypherGraphQuery(`MATCH (a)<-[r:USES_TYPE]-(b) WHERE a.qualified_name = "pkg.Target" AND b.name CONTAINS "Caller" RETURN count(r) LIMIT 1`)
 45		if !ok || !reverse.Count || reverse.Type != "USES_TYPE" || reverse.ToName != "pkg.Target" || reverse.FromNameContains != "Caller" || reverse.Limit != 1 {
 46			t.Fatalf("reverse filters = %+v ok=%t", reverse, ok)
 47		}
 48		for _, invalid := range []string{"plain text", `MATCH (a)-[r]-(b) RETURN r`, `MATCH (a)->[r]-(b) RETURN r`} {
 49			if got, ok := parseCypherGraphQuery(invalid); ok {
 50				t.Fatalf("invalid query parsed: %q => %+v", invalid, got)
 51			}
 52		}
 53	}
