 27	func TestSemanticWorktreePathFingerprintIncludesFilesAndExcludesIgnoredAndSymlinks(t *testing.T) {
 28		repoDir := t.TempDir()
 29		for rel, body := range map[string]string{
 30			"untracked/kept.go":          "package kept\n",
 31			"untracked/ignored/key.pem":  "secret-one\n",
 32			"untracked/ignored-file.pem": "secret-one\n",
 33		} {
 34			path := filepath.Join(repoDir, filepath.FromSlash(rel))
 35			if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
 36				t.Fatal(err)
 37			}
 38			if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
 39				t.Fatal(err)
 40			}
 41		}
 42		ignore := brainIgnore{patterns: []string{"untracked/ignored/**", "untracked/ignored-file.pem"}}
 43		base, baseBytes := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 44		if baseBytes == 0 {
 45			t.Fatal("included worktree file contributed no fingerprint bytes")
 46		}
 47		if _, singleBytes := semanticRegressionPathDigest(t, repoDir, "untracked/kept.go", ignore); singleBytes == 0 {
 48			t.Fatal("top-level untracked file contributed no fingerprint bytes")
 49		}
 50		if directLink, linkBytes := semanticRegressionPathDigest(t, repoDir, "untracked/linked.go", ignore); directLink != sha256.Sum256(nil) || linkBytes != 0 {
 51			t.Fatalf("top-level symlink contributed to fingerprint: %x bytes=%d", directLink, linkBytes)
 52		}
 53		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "kept.go"), []byte("package changed\n"), 0o600); err != nil {
 54			t.Fatal(err)
 55		}
 56		included, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 57		if included == base {
 58			t.Fatal("changing an included file did not change the worktree fingerprint")
 59		}
 60		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored", "key.pem"), []byte("secret-two\n"), 0o600); err != nil {
 61			t.Fatal(err)
 62		}
 63		ignored, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 64		if ignored != included {
 65			t.Fatal("changing an ignored file changed the worktree fingerprint")
 66		}
 67		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored-file.pem"), []byte("secret-two\n"), 0o600); err != nil {
 68			t.Fatal(err)
 69		}
 70		ignoredFile, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 71		if ignoredFile != ignored {
 72			t.Fatal("changing an ignored sibling file changed the worktree fingerprint")
 73		}
 74		missing, missingBytes := semanticRegressionPathDigest(t, repoDir, "missing", ignore)
 75		if missing != sha256.Sum256(nil) || missingBytes != 0 {
 76			t.Fatalf("missing path contributed to fingerprint: %x bytes=%d", missing, missingBytes)
 77		}
 78		t.Run("symlink paths", func(t *testing.T) {
 79			external := filepath.Join(t.TempDir(), "external.go")
 80			if err := os.WriteFile(external, []byte("external-one\n"), 0o600); err != nil {
 81				t.Fatal(err)
 82			}
 83			symlink := filepath.Join(repoDir, "untracked", "linked.go")
 84			if err := os.Symlink(external, symlink); err != nil {
 85				t.Skipf("symlink unavailable: %v", err)
 86			}
 87			if directLink, linkBytes := semanticRegressionPathDigest(t, repoDir, "untracked/linked.go", ignore); directLink != sha256.Sum256(nil) || linkBytes != 0 {
 88				t.Fatalf("top-level symlink contributed to fingerprint: %x bytes=%d", directLink, linkBytes)
 89			}
 90			if err := os.WriteFile(external, []byte("external-two\n"), 0o600); err != nil {
 91				t.Fatal(err)
 92			}
 93			linked, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
 94			if linked != ignoredFile {
 95				t.Fatal("changing a symlink target outside the repository changed the fingerprint")
 96			}
 97		})
 98	}
