  1065		if err := runSemanticIndex(cmd.Context(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
  1066			t.Fatalf("first index: %v", err)
  1067		}
  1068		second := &cobra.Command{Use: "index"}
