    15	func semanticRegressionPathDigest(t *testing.T, repoDir, clean string, ignore brainIgnore) ([32]byte, int64) {
    16		t.Helper()
    17		h := sha256.New()
    18		var total int64
    19		if err := appendWorktreePathContent(h, &total, repoDir, clean, ignore); err != nil {
    20			t.Fatal(err)
    21		}
    22		var sum [32]byte
    23		copy(sum[:], h.Sum(nil))
    24		return sum, total
    25	}
