			}
		})
	}
	unsafe := *source
	unsafe.SnapshotPath = "../outside/snapshot.ndjson"
	if _, err := semanticAuditSnapshotCoverage(brainDir, &unsafe, freshness); err == nil {
		t.Fatal("unsafe snapshot path produced coverage")
	}
}

